        return input().startswith("Yes")

def find_root(n, k):
    tree = TreeQuery()
    root = None
    current_depth = 1
    while n >= (k ** current_depth):
        for i in range(1, k ** current_depth + 1):
            if not tree.ask_query(i, i, i + k ** current_depth - 1):
                root = i
                return root
        current_depth += 1
    return root

