def find_path(scheme1: List[int]) -> List[List[int]]:
    def find(nums):
        parent, rank = [], [1 for _ in range(len(nums))]
        for i in range(len(nums)):
            if nums[i] not in [j[:len(nums) - len(i)] for j in parent]:
                for j in range(i + 1, len(nums)):
                    if nums[j][len(nums[j]) - len(i)] < len(nums[i]):
                        if len(nums[i]) > len(nums[j]) or (
                            len(nums[i]) == len(nums[j]) and nums[i][len(nums[i]) - 1] <= nums[j][len(nums[j]) - len(i) - 1]
                        ):
                            parent[j] = i
        for i in range(len(nums)):
            while nums[i] not in [j[:len(nums) - len(i)] - 1 for j in parent]:
                nums[i] = nums[i][:-1]
        return [tuple(nums[i]) for i in range(len(nums))], nums

    def cycle(nums1: tuple, nums2: tuple):
        if nums1[0] == nums2[0] or nums1[0] == nums2[0][1:]:
            for i in range(len(nums1)):
                nums2.append(nums1[i])
            return find(nums2)
        for i in range(len(nums2)):
            if nums1[0] == nums2[i] or nums1[0] == nums2[i][1:]:
                continue
            lca = cycle(nums1, nums2[i])
            if lca[-1] == nums1[0]:
                return lca + [nums1[0]][i:]
            nums2 = lca + nums2[:i] + [nums2[i]]
            return cycle(nums1, nums2)
        return []

    scheme1, scheme2 = find(scheme1)
    solution = cycle(scheme2, scheme1)
    while solution and tuple(solution[-1]) == scheme2[-1]:
        solution.pop()
    return solution if solution else [-1]

