import sys

def find_shortest_paths(edges, cities, height, n, k, diameter):
    # Implement Prim's algorithm to construct a minimum spanning tree (MST)
    visited = [False] * n
    mst_edges = []
    min_tree_edges = 0

    def find(x):
        if visited[x] == False:
            visited[x] = True
            return x
        visited[x] = True
        return find(edges[x])

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            edges[root_x] = root_y
            mst_edges.append((root_x, root_y, 1))
            visited[root_y] = True
            if abs(height[root_x] - height[root_y]) > 1:
                min_tree_edges += 1

    heights = []
    for i in range(cities):
        node = i
        if node > height:
            heights.append(i)
        if node < height:
            heights.append(node)

    for i in range(cities - 1):
        root_a = find(i)
        root_b = find(heights[i])
        if root_a != root_b:
            union(root_a, root_b)
            mst_edges.append((i, heights[i]))
            height[root_b] = min(height[root_b], heights[i])

    mst_edges.append((heights[-1], 0))

    if node > height:
        heights.pop()
        mst_edges.pop()
    diameter = len(mst_edges)

    if diameter + 1 <= k:
        return diameter, []
    else:
        return k - diameter - 1, mst_edges

