    if query == answer:
        root = 1 + answer  # Answer is on the path from root to query
    else:
        root = n + 1 - answer  # Answer is left behind from the query node path to the root
    root += 1  # Address the new tree label
    queries.append((query, root))

# Report the root of the tree
