        if len(sugars) == 1:
            return deque([(-1, sugars[0], -1, 0, None)])
        else:
            new_distances = deque()
            for sugars_used, u, v, d, good_paths in sugars:
                if self.edges[u] == v and self.edges[v] == u:
                    continue
                total_edge_count_used = -len(ended_at)
                for sugar in sugars_used:
                    total_edge_count_used += len(sugar)

                if total_edge_count_used < self.k:
                    continue
                start = deque()
                start.append((total_edge_count_used, u, v, d, tuple(good_paths)))

                if not blocked_game:
                    for ugly in self.find_shortcuts(u, v):
                        start.appendleft((len(sugars_used) + 1, ugly, v, d, tuple(set(good_paths) | {ugly})))
                    for ugly in self.find_shortcuts(v, u):
                        start.appendleft((len(sugars_used) + 1, v, ugly, d, tuple(set(good_paths) | {ugly})))

