                        v = sugar[3]
                        good = sugar[1] | set(sugar[4])
                        loser = sugar[0]

                        for dwarf in sugar[5]:
                            end.appendleft((len(sugar), dwarf, v, sugar[6], ({dwarf} | good) - {loser}))

                        new_distances.extend(end)

                        continue

