                    w = sugar[2]
                    b = sugar[3]
                    good = sugar[1] | set(sugar[4])
                    winner.append((len(sugar), sugar[0], w, b, sugar[1]))

                    end = deque()
                    end.appendleft((len(sugar), w, b, sugar[6], good))

                    new_distances.extend(end)
            return new_distances

