        blocked_game = sum(len(path) == 2 for path in self.edges) <= len(self.edges) * 2

        sugars = [(self.k, lgra, rgra, self, [lgra, rgra]) for lgra, rgra in [(i + 1, i + 2) for i in range(self.n - 1 - 1)]]
        sugars.extend([(self.k, i, i + 1, self, set()) for i in range(1, self.n - 1)])

        start = deque()
        start.appendleft((self.k, self, self, self, set()))

        if not blocked_game:
            sugars.appendleft((0))

        while start:
            sugars = self.get_ugly_distances(sugars, start)
            start = sugars.popleft()

            if len(sugars) == 1:
                for sugar in sugars:
                    yield sugar
                return

        raise Exception('Unexpected Situation')


