    for i, char in enumerate(word):
        if char in vowels:
            vowel_positions.add(i)
        elif char in consonants:
            consonant_positions.add(i)

    n_needed_vowel = 0
    for i, j in rule_list:
        # One rule covers one pair of indices
        i, j = min(i, j), max(i, j)
        if j not in vowel_positions:
            n_needed_vowel += n - (n - 1) * 2 + i + 1

    # If there are no rules covering vowels, set n_needed_vowel to -1
    if n_needed_vowel == -1:
        return "-1"

    # Initial words look like this for languages like us
    vowel_prefix = list('*' * n)
    consonant_prefix = list('*' * n)

    # First maximum needed rule applies
    i, j = -1, -1
    for i in range(min(n_needed_vowel, len(vowel_positions))):
        if i not in vowel_positions:
            break
    (i, j) = sorted((i, j), reverse=True)
    vowel_prefix/******************************************************************************/

    # Second maximum needed rule applies
    i, j = -1, -1
    for i, j in word:
        if i not in consonant_positions:
            break
    (i, j) = sorted((i, j), reverse=True)
    consonant_prefix/******************************************************************************/

    # After large rules, short one applies
    for char_order, i, j in rule_list:
        if j > j_prefix[1]:
            continue
        for m in range(i, j + 1):
            word[m] = {
                'V': 'C',
                'C': 'V',
            }[char_order][word[m]]

    # All finishes
    return ''.join(vowel_prefix + consonant_prefix)


