        sum_ = c.sum()
        queue.append([sum_, sum, num])
    c += card

c_sum = collections.Counter(card_sum_sum)
for (sum_, sum, num) in queue:
    c_sum[num % 11] = c_sum[num % 11] + 1
    for pre_sum in range(0, 11):
        c_sum[(sum_ + pre_sum) % 11] = c_sum[(sum_ + pre_sum) % 11] - 1

good_ways = 0
num_minorities = c_sum[0]
